-- Deities and Demigods: D&D pantheon divine stat blocks, batch C.
-- Source: Deities and Demigods (2002), Chapter 3, pp. 73-81.
-- Printed 3.0 statistics are preserved, with official 3.5 revision deltas recorded separately in mechanics JSON.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Fist holding a lightning bolt' WHERE source_id='dd-3.0' AND slug='heironeous' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Fist holding six red arrows' WHERE source_id='dd-3.0' AND slug='hextor' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Star of spears and maces' WHERE source_id='dd-3.0' AND slug='kord' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Gnome skull' WHERE source_id='dd-3.0' AND slug='kurtulmak' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-heironeous','Heironeous Divine Stat Block','73-75',
 'Heironeous the Invincible is a divine-rank-15 intermediate deity of valor, chivalry, justice, honor, war, and daring.',
 '{"deitySlug":"heironeous","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Invincible"],"symbol":"Fist holding a lightning bolt","homePlane":"Celestia","alignment":"LG","classes":[{"class":"Cleric","level":20},{"class":"Paladin","level":20}],"creature":{"type":"Outsider","subtypes":["Good"],"size":"Medium","hitDice":"20d8+180 outsider + 20d8+180 cleric + 20d10+180 paladin","hitPoints":1060,"initiative":"+12, always first","speed":{"land":60},"armorClass":{"total":89,"dexterity":8,"divine":15,"natural":28,"armor":10,"shield":7,"deflection":11},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"justicebringer":"+83/+78/+73/+68 melee; 1d8+48/17-20, +5 defending holy ghost touch longsword","spellTouch":{"melee":73,"ranged":83}},"saves":{"fort":56,"ref":55,"will":54,"intermediateDeityChecksAlways20":true},"abilities":{"str":47,"dex":27,"con":28,"int":25,"wis":25,"cha":33},"specialAttacks":{"smiteEvil":{"attackBonus":11,"damageBonus":60},"turnUndead":{"usesPerDay":14,"effectiveClericLevel":38}},"specialQualities":{"printedDamageReduction":"65/+5","printedFireResistance":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":36},"paladinFeatures":["aura of courage","detect evil","divine grace","divine health","lay on hands","remove disease 6/week","special mount","share spells with mount"]},"salientDivineAbilities":["Alter Reality","Alter Size","Area Divine Shield","Avatar","Battlesense","Divine Armor Mastery","Divine Blast","Divine Inspiration (courage)","Divine Paladin","Divine Shield","Divine Storm","Divine Weapon Focus (longsword)","Divine Weapon Specialization (longsword)","Gift of Life","Increased Damage Reduction","Lay Quest","Life and Death","Supreme Initiative"],"domainPowers":{"goodSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":25,"goodAndLawCasterLevel":26,"saveDc":"36 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"17 + spell level","paladinSpellsPerDay":"5/5/5/4","paladinBaseDc":"17 + spell level"},"possessions":{"justicebringer":"+5 defending holy ghost touch longsword; caster level 20"},"specialMount":{"type":"celestial heavy warhorse","hitDice":"12d8+36","hitPoints":73,"armorClass":24,"speedFeet":50,"spellResistance":25},"avatar":{"divineRank":7,"armorClass":73,"attacks":"Justicebringer +75/+70/+65/+60, 1d8+40/17-20","damageReduction":"42/+4","printedFireResistance":29,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":28},"saves":{"fort":48,"ref":47,"will":46},"salientDivineAbilities":["Alter Size","Battlesense","Divine Armor Mastery","Divine Blast","Divine Inspiration (courage)","Divine Paladin","Divine Shield","Divine Weapon Focus (longsword)","Divine Weapon Specialization (longsword)"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"28 + spell level"},"revision3_5":{"alignmentSubtypes":["good","lawful"],"damageReduction":"25/epic","fireResistance":20,"notes":"Apply 3.5 paladin features and terminology while preserving source class levels, divine rank, and printed 3.0 block."}}'),

('dd-statblock-hextor','Hextor Divine Stat Block','75-77',
 'Hextor is a divine-rank-15 intermediate deity of tyranny, war, discord, massacre, conflict, and ruthless martial discipline.',
