nus":20,"smiteDamageBonus":20},"spellLikeAbilities":{"casterLevel":25,"evilAndLawCasterLevel":26,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"17 + spell level"},"possessions":{"executioner":"+5 lawful unholy ghost touch light flail; caster level 20"},"avatar":{"divineRank":7,"armorClass":62,"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":50,"ref":46,"will":46},"salientDivineAbilities":["Alter Form","Alter Size","Divine Armor Mastery","Divine Inspiration (dread)","Divine Shield","Divine Weapon Mastery","Extra Domain (Destruction)","Lay Curse","Shift Form"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["evil","lawful"],"damageReduction":"25/epic","fireResistance":20,"notes":"Use 3.5 feat and combat terminology; retain six-arm source mechanics and divine statistics."}}'),

('dd-statblock-kord','Kord Divine Stat Block','77-79',
