 '{"deitySlug":"kord","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":14,"titles":["The Brawler"],"symbol":"Star of spears and maces","homePlane":"Ysgard","alignment":"CG","classes":[{"class":"Fighter","level":20},{"class":"Barbarian","level":20}],"creature":{"type":"Outsider","subtypes":["Chaotic","Good"],"size":"Medium","hitDice":"20d8+200 outsider + 20d10+200 fighter + 20d12+200 barbarian","hitPoints":1200,"initiative":12,"speed":{"land":70},"armorClass":{"total":68,"dexterity":8,"divine":14,"natural":27,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"kelmar":"+86/+81/+76/+71 melee, 2d6+54/17-20, +5 greatsword","spellTouch":{"melee":76,"ranged":62}},"saves":{"fort":58,"ref":54,"will":53,"intermediateDeityChecksAlways20":true},"abilities":{"str":55,"dex":27,"con":30,"int":24,"wis":24,"cha":29},"specialQualities":{"printedDamageReduction":["49/+4","4/-"],"printedFireResistance":34,"sonicResistance":34,"fastHealing":34,"spellResistance":46,"divineAura":{"radiusFeet":1400,"dc":33},"barbarianFeatures":["fast movement","uncanny dodge; cannot be flanked; +4 against traps"]},"salientDivineAbilities":["Alter Reality","Alter Size","Area Divine Shield","Avatar","Divine Battle Mastery","Divine Blast","Divine Blessing (Strength)","Divine Fast Healing","Divine Inspiration (courage)","Divine Rage","Divine Shield","Divine Weapon Focus (greatsword)","Divine Weapon Specialization (greatsword)","Extra Domain (Luck)","Extra Energy Resistance (sonic)","Gift of Life","Indomitable Strength"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1,"luckRerollsPerDay":14,"strengthUsesPerDay":14,"strengthEnhancementBonus":14},"spellLikeAbilities":{"casterLevel":24,"chaosAndGoodCasterLevel":25,"saveDc":"33 + spell level"},"divineRage":{"usesPerDay":14,"duration":"1 hour or until ended","notWindedAfterward":true,"armorClass":63,"hitPoints":1500,"attacks":"Kelmar +91/+86/+81/+76; 2d6+59/17-20","fireResistance":44,"sonicResistance":44,"spellResistance":56,"fort":63,"will":58,"strength":65,"constitution":40},"possessions":{"kelmar":{"base":"adamantine +5 greatsword","bane":"dragons","intelligence":24,"wisdom":24,"charisma":24,"alignment":"CG","communication":["speech","telepathy"],"atWill":["detect lawful evil alignment","find traps","detect magic","locate object 120 ft.","true seeing"],"threePerDay":["detect thoughts"],"specialPurpose":"slay lawful evil dragons","specialPurposePower":"on hit, lawful evil dragon Will DC 23 or dies","casterLevel":20,"weightPounds":15}},"avatar":{"divineRank":7,"armorClass":54,"attacks":"Kelmar +79/+74/+69/+64; 2d6+47/19-20","damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":51,"ref":47,"will":46},"salientDivineAbilities":["Divine Battle Mastery","Divine Fast Healing","Divine Inspiration (courage)","Divine Rage","Divine Shield","Divine Weapon Focus (greatsword)","Divine Weapon Specialization (greatsword)","Extra Domain (Luck)","Indomitable Strength"],"rage":{"usesPerDay":7,"duration":"1 hour or until ended","armorClass":49,"hitPoints":1500,"attacks":"+84/+79/+74/+69; 2d6+52/19-20","fireResistance":37,"sonicResistance":37,"spellResistance":49,"fort":56,"will":51,"strength":65,"constitution":40},"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"25/epic","fireResistance":19,"notes":"Retain explicit sonic resistance and fast healing from salient abilities; apply 3.5 barbarian/fighter class features and feat terminology."}}'),

('dd-statblock-kurtulmak','Kurtulmak Divine Stat Block','79-81',
 'Kurtulmak the Gnomesmasher is a divine-rank-15 intermediate deity of kobolds, trapmaking, mining, and war.',
 '{"deitySlug":"kurtulmak","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["Gnomesmasher","The Watcher"],"symbol":"Gnome skull","homePlane":"Baator","alignment":"LE","classes":[{"class":"Fighter","level":16},{"class":"Cleric","level":8},{"class":"Rogue","level":8},{"class":"Sorcerer","level":8}],"creature":{"type":"Outsider","subtypes":["Evil","Lawful"],"size":"Medium","hitDice":"20d8+200 outsider + 16d10+160 fighter + 8d8+80 cleric + 8d6+80 rogue + 8d4+80 sorcerer","hitPoints":1064,"initiative":"+21, always first","speed":{"land":60},"armorClass":{"total":79,"dexterity":17,"divine":15,"natural":28,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"shortspear":"+68/+63/+58/+53 melee, 1d8+17/18-20/x3, +5 keen lawful unholy shortspear","sting":"+68 melee, 1d4+5 plus poison/19-20","spellTouch":{"melee":62,"ranged":72}},"saves":{"fort":57,"ref":66,"will":56,"intermediateDeityChecksAlways20":true},"abilities":{"str":25,"dex":45,"con":31,"int":29,"wis":24,"cha":29},"specialQualities":{"koboldTraits":true,"printedDamageReduction":"50/+4","printedFireResistance":35,"fastHealing":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":33},"familiar":"rats","rogueFeatures":["evasion","traps","uncanny dodge; cannot be flanked"]},"specialAttacks":{"rebukeUndeadPerDay":12,"sneakAttack":"+4d6","poisonSting":{"fortitudeDc":65,"initial":"2d6 temporary Constitution","secondary":"2d6 temporary Constitution"}},"salientDivineAbilities":["Alter Reality","Alter Size","Avatar","Banestrike (gnomes)","Battlesense","Control Creatures (kobolds)","Divine Blast","Divine Dodge","Divine Fast Healing","Divine Shield","Divine Skill Focus (Craft [trapmaking])","Extra Domain (Law)","Grow Creature (kobolds)","Hand of Death","Mass Divine Blast","Supreme Initiative","Tunnel","Wound Enemy"],"domainPowers":{"evilSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1,"luckRerollsPerDay":15},"spellLikeAbilities":{"casterLevel":25,"evilAndLawCasterLevel":26,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/7/6/6/4","clericBaseDc":"17 + spell level","sorcererSpellsKnownPerDay":"6/9/8/7/5","sorcererBaseDc":"19 + spell level"},"uniqueAbilities":{"tunnel":{"requiresConcentration":true,"materials":["dirt","clay","sand","rock"],"maximumLengthFeet":150,"maximumCrossSection":"10 ft. square","startsAtDeityPosition":true}},"automaticActions":{"craftTrapmakingFreeActionDcMaximum":35,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":63,"attacks":{"shortspear":"+60/+55/+50/+45; 1d8+17/18-20/x3","sting":"+60; 1d4+5 plus poison/19-20"},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":25},"saves":{"fort":49,"ref":58,"will":48},"poisonFortitudeDc":57,"salientDivineAbilities":["Alter Size","Banestrike (gnomes)","Control Creatures (kobolds)","Divine Shield","Divine Skill Focus (Craft [trapmaking])","Extra Domain (Law)","Grow Creature (kobolds)","Tunnel","Wound Enemy"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["evil","lawful"],"damageReduction":"25/epic","fireResistance":20,"notes":"Apply 3.5 rogue/fighter/sorcerer/cleric terminology and class features while preserving source divine statistics and racial traits."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,d.description,0,NULL,1,
       'deity-statblock','statblock',0,1,'dd-dnd-pantheon',NULL,
       '["deities-and-demigods","deity","statblock","d&d-pantheon"]',d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
